  /// Registers `callback` for every `WindowEvent` this `Window` emits.
  ///
  /// The closure runs synchronously on the UI thread; the context is
  /// released through the C ABI when the listener is removed.
  @discardableResult public func addListener(_ callback: @escaping (WindowEvent) -> Void) -> ListenerId {
    let context = Unmanaged.passRetained(CallbackBox1<WindowEvent>(callback)).toOpaque()
    let trampoline: @convention(c) (UnsafePointer<native_window_event_t>?, UnsafeMutableRawPointer?) -> Void = { event, userData in
      guard let event, let userData, let value = WindowEvent(raw: event.pointee) else { return }
      Unmanaged<CallbackBox1<WindowEvent>>.fromOpaque(userData).takeUnretainedValue().body(value)
    }
    return native_window_add_listener(nativeHandle, trampoline, context, nativeapiReleaseUserData)
  }

  /// Unregisters a listener. Returns false if unknown.
  public func removeListener(_ listenerId: ListenerId) -> Bool {
    native_window_remove_listener(nativeHandle, listenerId)
  }

